import os
import requests


def get_identity_client(config):
    return requests.Session()


def load_identity_config():
    return {
        'domain_prefix': os.getenv('IDENTITY_DOMAIN_PREFIX'),
        'region': os.getenv('IDENTITY_REGION'),
        'client_id': os.getenv('IDENTITY_CLIENT_ID'),
        'client_secret': os.getenv('IDENTITY_CLIENT_SECRET'),
        'redirect_uri': os.getenv('IDENTITY_REDIRECT_URI')
    }

from typing import Dict


def normalize_claims(claims: Dict[str, str]) -> Dict[str, str]:
    return {
        'sub': claims.get('sub', ''),
        'name': claims.get('name', ''),
        'email': claims.get('email', ''),
        'picture': claims.get('picture', '')
    }

import json


def summarize_audit_events(audit_events):
    summary = {
        'total_events': len(audit_events),
        'successful_logins': sum(1 for event in audit_events if event['status'] == 'success'),
        'failed_logins': sum(1 for event in audit_events if event['status'] == 'failure')
    }
    return json.dumps(summary, indent=2)

import re


def moderate_claims(claims):
    moderated_claims = {}
    for key, value in claims.items():
        if key in ['name', 'email']:
            moderated_claims[key] = re.sub(r'[^a-zA-Z0-9@._-]', '', value)
        else:
            moderated_claims[key] = value
    return moderated_claims
